const items = $input.all();
const recipes = [];

for (const item of items) {
  const dataString = item.json.data;

  if (!dataString || typeof dataString !== 'string') continue;

  try {
    const parsedData = JSON.parse(dataString);

    if (!parsedData.data || !Array.isArray(parsedData.data)) continue;

    for (const element of parsedData.data) {
      if (!element.results || !Array.isArray(element.results)) continue;

      for (const result of element.results) {
        try {
          const jsonData = JSON.parse(result.html);

          let recipeData = null;
          if (jsonData['@type'] === 'Recipe') {
            recipeData = jsonData;
          } else if (jsonData['@graph']) {
            recipeData = jsonData['@graph'].find(item => item['@type'] === 'Recipe');
          }

          if (recipeData) {
            recipes.push({
              titre: recipeData.name,
              description: recipeData.description?.replace(/<[^>]*>/g, ''),
              categorie: recipeData.recipeCategory,
              temps_preparation: recipeData.prepTime,
              temps_cuisson: recipeData.cookTime,
              temps_total: recipeData.totalTime,
              portions: recipeData.recipeYield,
              ingredients: recipeData.recipeIngredient || [],
              etapes: (recipeData.recipeInstructions || []).map(step => ({
                nom: step.name || '',
                texte: step.text || step
              })),
              auteur: recipeData.author?.name || recipeData.author,
              image: Array.isArray(recipeData.image) ? recipeData.image[0] : recipeData.image,
              note: recipeData.aggregateRating ? {
                valeur: recipeData.aggregateRating.ratingValue,
                nombre_avis: recipeData.aggregateRating.reviewCount
              } : null,
              url: recipeData.url
            });
          }
        } catch (e) {
          console.error('Erreur parsing result.html:', e.message);
        }
      }
    }
  } catch (e) {
    console.error('Erreur parsing dataString:', e.message);
  }
}

// Retourner un JSON stringifié pour Ollama
return [{
  json: {
    recette_json: JSON.stringify(recipes[0] || {}, null, 2)
  }
}];

const matchedIngredients = $input.all();

function normalizeText(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[''`]/g, "'")
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getBaseForm(text) {
  const normalized = normalizeText(text);

  const variations = {
    'pommes de terre': 'pomme-de-terre',
    'pomme de terre': 'pomme-de-terre',
    'pdt': 'pomme-de-terre',
    'patates': 'pomme-de-terre',
    'pommes': 'pomme',
    'oeufs': 'oeuf',
    'tomates': 'tomate',
    'oignons': 'oignon',
    'gousses d\'ail': 'ail',
    'gousse d\'ail': 'ail',
    'pates': 'pate',
    'coquillettes': 'pate',
    'spaghettis': 'pate',
    'escalope de poulet': 'poulet',
    'escalopes de poulet': 'poulet',
    'filet de poulet': 'poulet',
    'filets de poulet': 'poulet',
    'blanc de poulet': 'poulet',
    'blancs de poulet': 'poulet',
    'cuisse de poulet': 'poulet',
    'cuisses de poulet': 'poulet',
    'filet de saumon': 'saumon',
    'pave de saumon': 'saumon',
    'boite de thon': 'thon',
    'fromage rape': 'fromage',
    'emmental rape': 'emmental',
    'gruyere rape': 'gruyere',
    'pain de mie': 'pain',
    'baguette': 'pain',
    'creme fraiche': 'creme',
    'creme liquide': 'creme',
    'beurre doux': 'beurre',
    'beurre demi-sel': 'beurre',
    'huile d\'olive': 'huile',
    'concentre de tomate': 'tomate',
    'tomates concassees': 'tomate',
    'coulis de tomate': 'tomate',
    'feuilles de lasagnes': 'lasagne',
    'feuilles de lasagne': 'lasagne',
    'feuilles d\'epinards': 'epinard',
    'feuilles d\'epinard': 'epinard',
    'pousses d\'epinards': 'epinard',
    'pousses d\'epinard': 'epinard',
    'feuilles de sauge': 'sauge',
    'feuilles de laurier': 'laurier'
  };

  if (variations[normalized]) {
    return variations[normalized];
  }

  let cleaned = normalized
    .replace(/^(un|une|des|du|de la|le|la|les)\s+/g, '')
    .replace(/^(feuilles?|pousses?|brins?|gousses?|tranches?)\s+(de|d')\s+/g, '')
    .replace(/\s+(de|d'|en)\s+/g, ' ')
    .replace(/\s+(frais|fraiche|rape|concasse|hache|tranche|entier|entiere)$/g, '');

  if (variations[cleaned]) {
    return variations[cleaned];
  }

  return slugify(cleaned.replace(/s$/, ''));
}

console.log('Nombre d\'items:', matchedIngredients.length);

return matchedIngredients.map(item => {
  const name = item.json.name || item.json.ingredient;
  const normalized = getBaseForm(name);

  console.log(`"${name}" → "${normalized}"`);

  return {
    json: {
      ...item.json,
      normalized_search: normalized
    }
  };
});

const ingredientItem = $input.all()[0].json;
const originalItem = $input.all()[1].json;

