const recipeId = $input.first().json.id;
const items = $input.all();

return items.map(item => ({
  json: {
    ...item.json,
    recipe_id: recipeId
  }
}));

let data = $input.item.json.output;

try {
  // Parse la string JSON
  if (typeof data === 'string') {
    data = JSON.parse(data);
  }

  // Vérifie que le parsing a fonctionné
  if (!data || !data.title || !data.ingredients) {
    return [{
      json: {
        error: 'Parsing failed or data incomplete',
        parsedData: data,
        originalData: $input.item.json.output
      }
    }];
  }

  return [
    {
      json: {
        type: 'recipe',
        title: data.title,
        description: data.description,
        category: data.category,
        servings: data.servings_default,
        prep_time: data.prep_time,
        cook_time: data.cook_time,
        total_time: data.minutes_total,
        difficulty: data.difficulty,
        season: data.season,
        instructions: data.instructions
      }
    },
    ...data.ingredients.map(ing => ({
      json: {
        type: 'ingredient',
        name: ing.name,
        quantity: ing.quantity,
        unit: ing.unit
      }
    }))
  ];

} catch (error) {
  return [{
    json: {
      error: error.message,
      stack: error.stack,
      originalData: $input.item.json.output
    }
  }];
}
